        CombinerState::Idle => true,
        CombinerState::Reading(_) => true, 
        CombinerState::AdvancingHead{idx, min_local_version} => {
            &&& idx <= self.num_replicas as nat
            &&& (forall |n| 0 <= n < idx ==> min_local_version <= self.local_versions[n])
