        CombinerState::AdvancingTail{observed_head} => {
            &&& (forall |n| 0 <= n < self.num_replicas as nat ==> observed_head <= self.local_versions[n])
        }
        CombinerState::Appending{cur_idx, tail} => {
            &&& self.local_versions[node_id] <= cur_idx <= tail
            &&& tail <= self.tail
