#[inductive(advance_tail_finish)]
fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) { admit(); }

#[inductive(append_flip_bit)]
fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) {
    assert forall |other| post.combiner.contains_key(other) && other != node_id
        ==> post.combiner[node_id].no_overlap_with(post.combiner[other]) by {
        assert(pre.combiner.contains_key(other));
        assert(pre.combiner[node_id].no_overlap_with(pre.combiner[other]));
        let CombinerState::Appending { cur_idx, tail } = pre.combiner[node_id];
        match pre.combiner[other] {
            CombinerState::Reading(ReaderState::Guard { start, end, cur, val }) => {
                assert(cur_idx > cur || tail <= cur);
                assert(cur_idx + 1 > cur || tail <= cur);
            },
            CombinerState::Appending { cur_idx: other_cur, tail: other_tail } => {
                assert(cur_idx >= other_tail || tail <= other_cur);
                assert(cur_idx + 1 >= other_tail || tail <= other_cur);
            },
            _ => {}
        }
    };
    assert forall |other| post.combiner.contains_key(other) && other != node_id
        ==> post.combiner[other].no_overlap_with(post.combiner[node_id]) by {
        assert(pre.combiner.contains_key(other));
        assert(pre.combiner[other].no_overlap_with(pre.combiner[node_id]));
        let CombinerState::Appending { cur_idx, tail } = pre.combiner[node_id];
        let CombinerState::Appending { cur_idx: post_cur, tail: post_tail } = post.combiner[node_id];
        assert(post_cur == cur_idx + 1);
        assert(post_tail == tail);
    };
    let min_local_head = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
    map_min_value_smallest(pre.local_versions, (pre.num_replicas - 1) as nat);
    assert forall |i: int|
        post.tail <= i < min_local_head + post.buffer_size
        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        assert(pre.tail <= i < min_local_head + pre.buffer_size);
        assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
        assert(pre.combiner[node_id] matches CombinerState::Appending { cur_idx, tail });
        assert(cur_idx < tail);
        assert(cur_idx >= (pre.tail as int) - (pre.buffer_size as int));
        assert(min_local_head <= pre.local_versions[node_id]);
        assert(pre.local_versions[node_id] <= cur_idx);
        assert(i < cur_idx + pre.buffer_size);
        assert(cur_idx <= i);
        log_entry_idx_wrap_around(cur_idx as nat, pre.buffer_size, i as nat);
        if i != cur_idx {
            assert(log_entry_idx(i, pre.buffer_size) != log_entry_idx(cur_idx, pre.buffer_size));
            assert(post.alive_bits[log_entry_idx(i, post.buffer_size) as nat]
                == pre.alive_bits[log_entry_idx(i, pre.buffer_size) as nat]);
        }
    };
}

